diff --git a/scripts/apply_repository_migration.py b/scripts/apply_repository_migration.py
new file mode 100644
index 0000000..ad4c1da
--- /dev/null
+++ b/scripts/apply_repository_migration.py
@@ -0,0 +1,166 @@
+"""Apply and verify the approved repository URL migration transaction."""
+
+from __future__ import annotations
+
+import argparse
+import hashlib
+import json
+from pathlib import Path
+from typing import Any
+
+APPROVED_MAP = Path("data/migrations/repository-approved-dispositions.json")
+REDIRECTS = Path("static/_redirects")
+ROLLBACK_MANIFEST = Path("data/migrations/repository-migration-rollback.json")
+
+
+def load_map(root: Path) -> dict[str, Any]:
+    path = root / APPROVED_MAP
+    loaded = json.loads(path.read_text(encoding="utf-8"))
+    if loaded.get("approval", {}).get("status") != "approved":
+        raise ValueError("Repository migration map is not approved")
+    if loaded.get("counts") != {"keep": 11, "redirect": 1, "retire": 262, "total": 274}:
+        raise ValueError("Approved repository migration counts changed")
+    return loaded
+
+
+def expected_redirects(records: list[dict[str, Any]]) -> str:
+    redirects = [record for record in records if record["disposition"] == "redirect"]
+    if len(redirects) != 1:
+        raise ValueError("Exactly one redirect is required")
+    source = redirects[0]
+    target = source["destination"]
+    target_record = next((record for record in records if record["url"] == target), None)
+    if not target_record or target_record["disposition"] != "keep":
+        raise ValueError(f"Redirect target is not retained: {target}")
+    if target == source["url"]:
+        raise ValueError("Redirect loop detected")
+    return f"{source['url']} {target} 301\n"
+
+
+def removed_source_paths(records: list[dict[str, Any]]) -> list[str]:
+    redirected_sources = {
+        record["source_path"] for record in records if record["disposition"] == "redirect"
+    }
+    return sorted(
+        {
+            record["source_path"]
+            for record in records
+            if record["url_type"] == "canonical"
+            and record["disposition"] == "retire"
+            and record["source_path"] not in redirected_sources
+        }
+    )
+
+
+def render_manifest(root: Path, data: dict[str, Any]) -> str:
+    records = data["records"]
+    by_path = {record["source_path"]: record for record in records}
+    removed = [
+        {"path": relative, "sha256": by_path[relative]["source_checksum"]}
+        for relative in removed_source_paths(records)
+    ]
+    return (
+        json.dumps(
+            {
+                "schema_version": "1.0.0",
+                "pre_migration_commit": data["approval"]["approved_commit"],
+                "approved_map": APPROVED_MAP.as_posix(),
+                "approved_map_sha256": hashlib.sha256(
+                    (root / APPROVED_MAP).read_bytes()
+                ).hexdigest(),
+                "removed_sources": removed,
+                "rollback": (
+                    "Restore listed files and content/repo/odysseus-dev-odysseus/index.md "
+                    "from pre_migration_commit, remove static/_redirects, rebuild, and redeploy."
+                ),
+            },
+            indent=2,
+            sort_keys=True,
+        )
+        + "\n"
+    )
+
+
+def remove_alias(path: Path, alias: str) -> None:
+    lines = path.read_text(encoding="utf-8").splitlines(keepends=True)
+    alias_line = f"- {alias}\n"
+    try:
+        index = lines.index(alias_line)
+    except ValueError as error:
+        if alias not in path.read_text(encoding="utf-8"):
+            return
+        raise ValueError(
+            f"Approved alias has an unexpected representation in {path}: {alias}"
+        ) from error
+    del lines[index]
+    if index and lines[index - 1].strip() == "aliases:":
+        del lines[index - 1]
+    path.write_text("".join(lines), encoding="utf-8")
+
+
+def apply(root: Path) -> None:
+    data = load_map(root)
+    records = data["records"]
+    manifest = render_manifest(root, data)
+    for relative in removed_source_paths(records):
+        path = root / relative
+        if path.exists():
+            record = next(record for record in records if record["source_path"] == relative)
+            if hashlib.sha256(path.read_bytes()).hexdigest() != record["source_checksum"]:
+                raise ValueError(f"Approved source changed before deletion: {relative}")
+            path.unlink()
+    for record in records:
+        if record["disposition"] == "redirect":
+            remove_alias(root / record["source_path"], record["url"])
+    redirects = root / REDIRECTS
+    redirects.parent.mkdir(parents=True, exist_ok=True)
+    redirects.write_text(expected_redirects(records), encoding="utf-8")
+    manifest_path = root / ROLLBACK_MANIFEST
+    manifest_path.parent.mkdir(parents=True, exist_ok=True)
+    manifest_path.write_text(manifest, encoding="utf-8")
+
+
+def check(root: Path) -> None:
+    data = load_map(root)
+    records = data["records"]
+    redirects = root / REDIRECTS
+    if not redirects.exists() or redirects.read_text(encoding="utf-8") != expected_redirects(
+        records
+    ):
+        raise ValueError("Hosting redirects differ from the approved map")
+    for relative in removed_source_paths(records):
+        if (root / relative).exists():
+            raise ValueError(f"Retired source still exists: {relative}")
+    for record in records:
+        if record["disposition"] == "keep" and record["url_type"] == "canonical":
+            if not (root / record["source_path"]).exists():
+                raise ValueError(f"Retained source is missing: {record['source_path']}")
+        if record["disposition"] == "redirect":
+            text = (root / record["source_path"]).read_text(encoding="utf-8")
+            if record["url"] in text:
+                raise ValueError(f"Redirect alias still emits a Hugo page: {record['url']}")
+    manifest = root / ROLLBACK_MANIFEST
+    if not manifest.exists():
+        raise ValueError("Rollback manifest is missing")
+
+
+def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
+    parser = argparse.ArgumentParser(description=__doc__)
+    parser.add_argument("--root", type=Path, default=Path.cwd())
+    mode = parser.add_mutually_exclusive_group(required=True)
+    mode.add_argument("--apply", action="store_true")
+    mode.add_argument("--check", action="store_true")
+    return parser.parse_args(argv)
+
+
+def main(argv: list[str] | None = None) -> int:
+    args = parse_args(argv)
+    root = args.root.resolve()
+    if args.apply:
+        apply(root)
+    check(root)
+    return 0
+
+
+if __name__ == "__main__":
+    raise SystemExit(main())
diff --git a/scripts/capture_repository_production_snapshot.py b/scripts/capture_repository_production_snapshot.py
new file mode 100644
index 0000000..7f89391
--- /dev/null
+++ b/scripts/capture_repository_production_snapshot.py
@@ -0,0 +1,152 @@
+"""Capture the live repository URL surface for BR-003 migration review."""
+
+from __future__ import annotations
+
+import argparse
+import json
+import urllib.error
+import urllib.request
+import xml.etree.ElementTree as ET
+from concurrent.futures import ThreadPoolExecutor
+from datetime import date
+from pathlib import Path
+from typing import Any
+
+SCHEMA_VERSION = "1.0.0"
+INVENTORY_PATH = Path("data/derived/observatory/repository-url-inventory.json")
+OUTPUT_PATH = Path("data/derived/observatory/repository-production-snapshot.json")
+
+
+def _sitemap_paths(data: bytes, site_origin: str) -> set[str]:
+    root = ET.fromstring(data)
+    namespace = {"s": "http://www.sitemaps.org/schemas/sitemap/0.9"}
+    return {
+        element.text.removeprefix(site_origin)
+        for element in root.findall("s:url/s:loc", namespace)
+        if element.text and element.text.startswith(f"{site_origin}/repo/")
+    }
+
+
+def _http_status(url: str) -> int:
+    request = urllib.request.Request(url, method="HEAD", headers={"User-Agent": "Claracle/BR-003"})
+    try:
+        with urllib.request.urlopen(request, timeout=20) as response:
+            return int(response.status)
+    except urllib.error.HTTPError as error:
+        return int(error.code)
+    except urllib.error.URLError:
+        return 0
+
+
+def build_snapshot(
+    inventory: dict[str, Any],
+    *,
+    site_origin: str,
+    captured_at: date,
+    sitemap_data: bytes,
+    status_getter: Any = _http_status,
+) -> dict[str, Any]:
+    sitemap_url = f"{site_origin}/sitemap.xml"
+    sitemap_paths = _sitemap_paths(sitemap_data, site_origin)
+    urls = [record["url"] for record in inventory["records"]]
+    with ThreadPoolExecutor(max_workers=12) as executor:
+        statuses = dict(
+            zip(
+                urls,
+                executor.map(lambda path: status_getter(f"{site_origin}{path}"), urls),
+                strict=True,
+            )
+        )
+    records = [
+        {
+            "url": record["url"],
+            "url_type": record["url_type"],
+            "canonical_url": record["canonical_url"],
+            "in_sitemap": record["url"] in sitemap_paths,
+            "http_status": statuses[record["url"]],
+        }
+        for record in inventory["records"]
+    ]
+    local_urls = set(urls)
+    production_only = sorted(sitemap_paths - local_urls)
+    return {
+        "schema_version": SCHEMA_VERSION,
+        "captured_at": captured_at.isoformat(),
+        "site_origin": site_origin,
+        "sources": {
+            "sitemap": sitemap_url,
+            "http_method": "HEAD",
+            "url_inspection": "not_collected",
+            "search_analytics": "not_collected",
+            "sampled_links": "not_collected",
+            "first_party_referrals": "not_collected",
+        },
+        "counts": {
+            "local_urls": len(local_urls),
+            "sitemap_urls": len(sitemap_paths),
+            "http_200": sum(record["http_status"] == 200 for record in records),
+            "http_404": sum(record["http_status"] == 404 for record in records),
+            "http_other_or_unavailable": sum(
+                record["http_status"] not in {200, 404} for record in records
+            ),
+            "production_only": len(production_only),
+        },
+        "production_only_urls": production_only,
+        "records": records,
+    }
+
+
+def validate_snapshot(snapshot: dict[str, Any], inventory: dict[str, Any]) -> None:
+    inventory_urls = {record["url"] for record in inventory["records"]}
+    snapshot_urls = {record["url"] for record in snapshot.get("records", [])}
+    if inventory_urls != snapshot_urls:
+        raise ValueError("Production snapshot does not cover the current repository URL inventory")
+    if snapshot["counts"]["local_urls"] != len(inventory_urls):
+        raise ValueError("Production snapshot local URL count is inconsistent")
+    if snapshot["counts"]["production_only"] != len(snapshot["production_only_urls"]):
+        raise ValueError("Production-only URL count is inconsistent")
+    unavailable = [record["url"] for record in snapshot["records"] if record["http_status"] == 0]
+    if unavailable:
+        raise ValueError(
+            "Production snapshot contains unavailable HTTP evidence: " + ", ".join(unavailable)
+        )
+
+
+def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
+    parser = argparse.ArgumentParser(description=__doc__)
+    parser.add_argument("--root", type=Path, default=Path.cwd())
+    parser.add_argument("--site-origin", default="https://claracle.com")
+    parser.add_argument("--captured-at", type=date.fromisoformat)
+    parser.add_argument("--check", action="store_true")
+    return parser.parse_args(argv)
+
+
+def main(argv: list[str] | None = None) -> int:
+    args = parse_args(argv)
+    root = args.root.resolve()
+    inventory = json.loads((root / INVENTORY_PATH).read_text(encoding="utf-8"))
+    output = root / OUTPUT_PATH
+    if args.check:
+        if not output.exists():
+            raise SystemExit(f"Repository production snapshot is missing: {OUTPUT_PATH}")
+        validate_snapshot(json.loads(output.read_text(encoding="utf-8")), inventory)
+        return 0
+    if args.captured_at is None:
+        raise SystemExit("--captured-at is required when capturing production evidence")
+    sitemap_url = f"{args.site_origin}/sitemap.xml"
+    with urllib.request.urlopen(sitemap_url, timeout=30) as response:
+        sitemap_data = response.read()
+    snapshot = build_snapshot(
+        inventory,
+        site_origin=args.site_origin.rstrip("/"),
+        captured_at=args.captured_at,
+        sitemap_data=sitemap_data,
+    )
+    validate_snapshot(snapshot, inventory)
+    output.parent.mkdir(parents=True, exist_ok=True)
+    output.write_text(json.dumps(snapshot, indent=2, sort_keys=True) + "\n", encoding="utf-8")
+    return 0
+
+
+if __name__ == "__main__":
+    raise SystemExit(main())
diff --git a/scripts/capture_repository_url_inspection.py b/scripts/capture_repository_url_inspection.py
new file mode 100644
index 0000000..762d51e
--- /dev/null
+++ b/scripts/capture_repository_url_inspection.py
@@ -0,0 +1,175 @@
+"""Capture Search Console URL Inspection evidence for repository URLs."""
+
+from __future__ import annotations
+
+import argparse
+import json
+import time
+import urllib.error
+import urllib.request
+from collections import Counter
+from concurrent.futures import ThreadPoolExecutor
+from datetime import datetime, timezone
+from pathlib import Path
+from typing import Any, Callable
+
+SCHEMA_VERSION = "1.0.0"
+INVENTORY_PATH = Path("data/derived/observatory/repository-url-inventory.json")
+OUTPUT_PATH = Path("data/derived/observatory/repository-url-inspection.json")
+ENDPOINT = "https://searchconsole.googleapis.com/v1/urlInspection/index:inspect"
+
+
+def inspect_url(
+    inspection_url: str,
+    *,
+    site_url: str,
+    token: str,
+    attempts: int = 4,
+) -> dict[str, Any]:
+    body = json.dumps(
+        {
+            "inspectionUrl": inspection_url,
+            "siteUrl": site_url,
+            "languageCode": "en-US",
+        }
+    ).encode()
+    request = urllib.request.Request(
+        ENDPOINT,
+        data=body,
+        method="POST",
+        headers={
+            "Authorization": f"Bearer {token}",
+            "Content-Type": "application/json",
+            "User-Agent": "Claracle/BR-003",
+        },
+    )
+    for attempt in range(attempts):
+        try:
+            with urllib.request.urlopen(request, timeout=30) as response:
+                return json.loads(response.read())
+        except urllib.error.HTTPError as error:
+            if error.code not in {429, 500, 502, 503, 504} or attempt == attempts - 1:
+                detail = error.read().decode("utf-8", errors="replace")
+                raise RuntimeError(
+                    f"URL Inspection failed for {inspection_url}: HTTP {error.code}: {detail}"
+                ) from error
+            time.sleep(2**attempt)
+        except (TimeoutError, urllib.error.URLError) as error:
+            if attempt == attempts - 1:
+                raise RuntimeError(
+                    f"URL Inspection network failure for {inspection_url}: {error}"
+                ) from error
+            time.sleep(2**attempt)
+    raise RuntimeError(f"URL Inspection failed for {inspection_url}")
+
+
+def build_snapshot(
+    inventory: dict[str, Any],
+    *,
+    site_origin: str,
+    site_url: str,
+    captured_at: str,
+    inspector: Callable[[str], dict[str, Any]],
+) -> dict[str, Any]:
+    items = inventory["records"]
+    inspection_urls = [f"{site_origin}{item['url']}" for item in items]
+    with ThreadPoolExecutor(max_workers=4) as executor:
+        responses = list(executor.map(inspector, inspection_urls))
+
+    records = []
+    for item, inspection_url, response in zip(
+        items,
+        inspection_urls,
+        responses,
+        strict=True,
+    ):
+        result = response.get("inspectionResult", {})
+        index = result.get("indexStatusResult", {})
+        records.append(
+            {
+                "url": item["url"],
+                "inspection_url": inspection_url,
+                "inspection_result_link": result.get("inspectionResultLink"),
+                "verdict": index.get("verdict"),
+                "coverage_state": index.get("coverageState"),
+                "robots_txt_state": index.get("robotsTxtState"),
+                "indexing_state": index.get("indexingState"),
+                "page_fetch_state": index.get("pageFetchState"),
+                "last_crawl_time": index.get("lastCrawlTime"),
+                "user_canonical": index.get("userCanonical"),
+                "google_canonical": index.get("googleCanonical"),
+                "referring_urls": index.get("referringUrls", []),
+                "sitemaps": index.get("sitemap", []),
+            }
+        )
+
+    verdicts = Counter(record["verdict"] or "UNSPECIFIED" for record in records)
+    coverage = Counter(record["coverage_state"] or "UNSPECIFIED" for record in records)
+    return {
+        "schema_version": SCHEMA_VERSION,
+        "captured_at": captured_at,
+        "site_origin": site_origin,
+        "site_url": site_url,
+        "counts": {
+            "total": len(records),
+            "verdicts": dict(sorted(verdicts.items())),
+            "coverage_states": dict(sorted(coverage.items())),
+        },
+        "records": records,
+    }
+
+
+def validate_snapshot(snapshot: dict[str, Any], inventory: dict[str, Any]) -> None:
+    expected = {record["url"] for record in inventory["records"]}
+    actual = {record["url"] for record in snapshot.get("records", [])}
+    if expected != actual or len(snapshot.get("records", [])) != len(expected):
+        raise ValueError("URL Inspection snapshot does not cover the current inventory")
+    incomplete = [
+        record["url"]
+        for record in snapshot["records"]
+        if not record["verdict"] or not record["coverage_state"]
+    ]
+    if incomplete:
+        raise ValueError("URL Inspection returned incomplete evidence: " + ", ".join(incomplete))
+
+
+def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
+    parser = argparse.ArgumentParser(description=__doc__)
+    parser.add_argument("--root", type=Path, default=Path.cwd())
+    parser.add_argument("--site-origin", default="https://claracle.com")
+    parser.add_argument("--site-url", default="sc-domain:claracle.com")
+    parser.add_argument("--token-file", type=Path)
+    parser.add_argument("--check", action="store_true")
+    return parser.parse_args(argv)
+
+
+def main(argv: list[str] | None = None) -> int:
+    args = parse_args(argv)
+    root = args.root.resolve()
+    inventory = json.loads((root / INVENTORY_PATH).read_text(encoding="utf-8"))
+    output = root / OUTPUT_PATH
+    if args.check:
+        if not output.exists():
+            raise SystemExit(f"URL Inspection snapshot is missing: {OUTPUT_PATH}")
+        validate_snapshot(json.loads(output.read_text(encoding="utf-8")), inventory)
+        return 0
+    if args.token_file is None:
+        raise SystemExit("--token-file is required when capturing URL Inspection evidence")
+    token = args.token_file.read_text(encoding="utf-8").strip()
+    if not token:
+        raise SystemExit("URL Inspection token file is empty")
+    snapshot = build_snapshot(
+        inventory,
+        site_origin=args.site_origin.rstrip("/"),
+        site_url=args.site_url,
+        captured_at=datetime.now(timezone.utc).isoformat(),
+        inspector=lambda url: inspect_url(url, site_url=args.site_url, token=token),
+    )
+    validate_snapshot(snapshot, inventory)
+    output.parent.mkdir(parents=True, exist_ok=True)
+    output.write_text(json.dumps(snapshot, indent=2, sort_keys=True) + "\n", encoding="utf-8")
+    return 0
+
+
+if __name__ == "__main__":
+    raise SystemExit(main())
