diff --git a/tests/test_apply_repository_migration.py b/tests/test_apply_repository_migration.py
new file mode 100644
index 0000000..c90b529
--- /dev/null
+++ b/tests/test_apply_repository_migration.py
@@ -0,0 +1,84 @@
+from __future__ import annotations
+
+import hashlib
+from pathlib import Path
+
+import pytest
+
+from scripts import apply_repository_migration as migration
+
+
+def _record(
+    url: str,
+    disposition: str,
+    path: str,
+    content: str,
+    *,
+    url_type: str = "canonical",
+    destination: str = "",
+) -> dict[str, str]:
+    return {
+        "url": url,
+        "url_type": url_type,
+        "canonical_url": url,
+        "source_path": path,
+        "source_checksum": hashlib.sha256(content.encode()).hexdigest(),
+        "disposition": disposition,
+        "destination": destination,
+    }
+
+
+def _migration_data(root: Path) -> dict[str, object]:
+    target_content = "---\naliases:\n- /repo/old/\n---\n"
+    retired_content = "---\ntitle: retired\n---\n"
+    target_path = "content/repo/target/index.md"
+    retired_path = "content/repo/retired/index.md"
+    for relative, content in (
+        (target_path, target_content),
+        (retired_path, retired_content),
+    ):
+        path = root / relative
+        path.parent.mkdir(parents=True, exist_ok=True)
+        path.write_text(content, encoding="utf-8")
+    approved_path = root / migration.APPROVED_MAP
+    approved_path.parent.mkdir(parents=True, exist_ok=True)
+    approved_path.write_text("{}\n", encoding="utf-8")
+    return {
+        "approval": {"approved_commit": "abc123"},
+        "records": [
+            _record("/repo/target/", "keep", target_path, target_content),
+            _record(
+                "/repo/old/",
+                "redirect",
+                target_path,
+                target_content,
+                url_type="alias",
+                destination="/repo/target/",
+            ),
+            _record("/repo/retired/", "retire", retired_path, retired_content),
+        ],
+    }
+
+
+def test_apply_removes_source_alias_and_writes_rollback(
+    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
+) -> None:
+    data = _migration_data(tmp_path)
+    monkeypatch.setattr(migration, "load_map", lambda _root: data)
+
+    migration.apply(tmp_path)
+    migration.check(tmp_path)
+
+    assert not (tmp_path / "content/repo/retired/index.md").exists()
+    assert "/repo/old/" not in (tmp_path / "content/repo/target/index.md").read_text()
+    assert (tmp_path / migration.REDIRECTS).read_text() == ("/repo/old/ /repo/target/ 301\n")
+    assert (tmp_path / migration.ROLLBACK_MANIFEST).exists()
+
+
+def test_apply_rejects_changed_source(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
+    data = _migration_data(tmp_path)
+    (tmp_path / "content/repo/retired/index.md").write_text("changed\n", encoding="utf-8")
+    monkeypatch.setattr(migration, "load_map", lambda _root: data)
+
+    with pytest.raises(ValueError, match="changed before deletion"):
+        migration.apply(tmp_path)
diff --git a/tests/test_capture_repository_production_snapshot.py b/tests/test_capture_repository_production_snapshot.py
new file mode 100644
index 0000000..3bfbe6c
--- /dev/null
+++ b/tests/test_capture_repository_production_snapshot.py
@@ -0,0 +1,84 @@
+from __future__ import annotations
+
+from datetime import date
+
+import pytest
+
+from scripts import capture_repository_production_snapshot as snapshot
+
+
+def _inventory() -> dict[str, object]:
+    return {
+        "records": [
+            {
+                "url": "/repo/",
+                "url_type": "index",
+                "canonical_url": "/repo/",
+            },
+            {
+                "url": "/repo/alpha/",
+                "url_type": "canonical",
+                "canonical_url": "/repo/alpha/",
+            },
+        ]
+    }
+
+
+def _sitemap(*paths: str) -> bytes:
+    entries = "".join(f"https://claracle.com{path}" for path in paths)
+    return (
+        ''
+        ''
+        f"{entries}"
+    ).encode()
+
+
+def test_build_snapshot_reconciles_sitemap_http_and_production_only_urls() -> None:
+    statuses = {
+        "https://claracle.com/repo/": 200,
+        "https://claracle.com/repo/alpha/": 404,
+    }
+
+    payload = snapshot.build_snapshot(
+        _inventory(),
+        site_origin="https://claracle.com",
+        captured_at=date(2026, 8, 10),
+        sitemap_data=_sitemap("/repo/", "/repo/production-only/"),
+        status_getter=statuses.__getitem__,
+    )
+
+    assert payload["counts"] == {
+        "local_urls": 2,
+        "sitemap_urls": 2,
+        "http_200": 1,
+        "http_404": 1,
+        "http_other_or_unavailable": 0,
+        "production_only": 1,
+    }
+    assert payload["production_only_urls"] == ["/repo/production-only/"]
+    assert payload["sources"]["search_analytics"] == "not_collected"
+
+
+def test_validate_snapshot_rejects_incomplete_coverage() -> None:
+    payload = {
+        "counts": {"local_urls": 1, "production_only": 0},
+        "production_only_urls": [],
+        "records": [{"url": "/repo/"}],
+    }
+
+    with pytest.raises(ValueError, match="does not cover"):
+        snapshot.validate_snapshot(payload, _inventory())
+
+
+def test_validate_snapshot_rejects_unavailable_http_evidence() -> None:
+    payload = {
+        "counts": {"local_urls": 2, "production_only": 0},
+        "production_only_urls": [],
+        "records": [
+            {"url": "/repo/", "http_status": 200},
+            {"url": "/repo/alpha/", "http_status": 0},
+        ],
+    }
+
+    with pytest.raises(ValueError, match="unavailable HTTP evidence"):
+        snapshot.validate_snapshot(payload, _inventory())
diff --git a/tests/test_capture_repository_url_inspection.py b/tests/test_capture_repository_url_inspection.py
new file mode 100644
index 0000000..5e0c57a
--- /dev/null
+++ b/tests/test_capture_repository_url_inspection.py
@@ -0,0 +1,83 @@
+from __future__ import annotations
+
+import json
+
+from scripts import capture_repository_url_inspection as inspection
+
+
+def test_build_snapshot_normalizes_index_evidence() -> None:
+    inventory = {"records": [{"url": "/repo/"}, {"url": "/repo/alpha/"}]}
+
+    def inspect(url: str) -> dict[str, object]:
+        known = url.endswith("/alpha/")
+        return {
+            "inspectionResult": {
+                "inspectionResultLink": f"https://search.google.com/inspect/{known}",
+                "indexStatusResult": {
+                    "verdict": "PASS" if known else "NEUTRAL",
+                    "coverageState": "Submitted and indexed"
+                    if known
+                    else "URL is unknown to Google",
+                    "indexingState": "INDEXING_ALLOWED" if known else "INDEXING_STATE_UNSPECIFIED",
+                    "pageFetchState": "SUCCESSFUL" if known else "PAGE_FETCH_STATE_UNSPECIFIED",
+                },
+            }
+        }
+
+    payload = inspection.build_snapshot(
+        inventory,
+        site_origin="https://claracle.com",
+        site_url="sc-domain:claracle.com",
+        captured_at="2026-08-11T09:00:00+00:00",
+        inspector=inspect,
+    )
+
+    assert payload["counts"]["total"] == 2
+    assert payload["counts"]["verdicts"] == {"NEUTRAL": 1, "PASS": 1}
+    assert payload["records"][1]["coverage_state"] == "Submitted and indexed"
+
+
+def test_validate_snapshot_rejects_incomplete_coverage() -> None:
+    inventory = {"records": [{"url": "/repo/"}]}
+    snapshot = {"records": []}
+
+    try:
+        inspection.validate_snapshot(snapshot, inventory)
+    except ValueError as error:
+        assert "does not cover" in str(error)
+    else:
+        raise AssertionError("Expected incomplete snapshot to fail")
+
+
+def test_inspect_url_retries_timeout_and_sends_bearer_token(monkeypatch) -> None:
+    requests = []
+
+    class Response:
+        def __enter__(self):
+            return self
+
+        def __exit__(self, *_args):
+            return None
+
+        def read(self) -> bytes:
+            return json.dumps({"inspectionResult": {}}).encode()
+
+    def urlopen(request, timeout):
+        requests.append((request, timeout))
+        if len(requests) == 1:
+            raise TimeoutError("transient")
+        return Response()
+
+    monkeypatch.setattr(inspection.urllib.request, "urlopen", urlopen)
+    monkeypatch.setattr(inspection.time, "sleep", lambda _seconds: None)
+
+    result = inspection.inspect_url(
+        "https://claracle.com/repo/",
+        site_url="sc-domain:claracle.com",
+        token="secret-token",
+    )
+
+    assert result == {"inspectionResult": {}}
+    assert len(requests) == 2
+    assert requests[1][0].get_header("Authorization") == "Bearer secret-token"
+    assert requests[1][1] == 30
diff --git a/tests/test_cloudflare_pages_workflows.py b/tests/test_cloudflare_pages_workflows.py
