index 0000000..4f0e1be
--- /dev/null
+++ b/tests/test_cloudflare_pages_workflows.py
@@ -0,0 +1,50 @@
+from __future__ import annotations
+
+from pathlib import Path
+
+import yaml
+
+
+def _workflow(path: str) -> dict:
+    return yaml.safe_load(Path(path).read_text(encoding="utf-8"))
+
+
+def test_production_workflows_use_one_pinned_cloudflare_boundary() -> None:
+    for relative in (
+        ".github/workflows/deploy-site.yml",
+        ".github/workflows/crawl-and-publish.yml",
+    ):
+        text = Path(relative).read_text(encoding="utf-8")
+        workflow = _workflow(relative)
+        deploy = workflow["jobs"]["deploy"]
+        rendered_steps = "\n".join(
+            f"{step.get('uses', '')}\n{step.get('run', '')}\n{step.get('with', '')}"
+            for step in deploy["steps"]
+        )
+        assert "actions/configure-pages@" not in text
+        assert "actions/deploy-pages@" not in text
+        assert "actions/upload-pages-artifact@" not in text
+        assert (
+            "cloudflare/wrangler-action@9acf94ace14e7dc412b076f2c5c20b8ce93c79cd" in rendered_steps
+        )
+        assert "wranglerVersion': '4.120.1" in rendered_steps
+        assert "pages deploy public --project-name=claracle --branch=main" in rendered_steps
+        assert "secrets.CLOUDFLARE_API_TOKEN" in rendered_steps
+        assert "secrets.CLOUDFLARE_ACCOUNT_ID" in rendered_steps
+        assert "scripts/verify_repository_migration_http.py" in rendered_steps
+        assert deploy["environment"]["name"] == "cloudflare-pages"
+
+
+def test_repository_source_is_not_hydrated_from_publish() -> None:
+    for relative in (
+        ".github/workflows/deploy-site.yml",
+        ".github/workflows/crawl-and-publish.yml",
+        ".github/workflows/generate-data-pages.yml",
+    ):
+        assert "content/repo/" not in Path(relative).read_text(encoding="utf-8")
+
+
+def test_approved_redirect_rule_is_one_hop_and_permanent() -> None:
+    assert Path("static/_redirects").read_text(encoding="utf-8") == (
+        "/repo/pewdiepie-archdaemon-odysseus/ /repo/odysseus-dev-odysseus/ 301\n"
+    )
diff --git a/tests/test_generate_repository_approved_dispositions.py b/tests/test_generate_repository_approved_dispositions.py
new file mode 100644
index 0000000..161e099
--- /dev/null
+++ b/tests/test_generate_repository_approved_dispositions.py
@@ -0,0 +1,76 @@
+from __future__ import annotations
+
+import hashlib
+import json
+from pathlib import Path
+
+import pytest
+
+from scripts import generate_repository_approved_dispositions as approved
+
+
+def _write_inputs(root: Path) -> None:
+    records = []
+    inventory = []
+    for index in range(274):
+        if index < 11:
+            disposition = "keep"
+        elif index == 11:
+            disposition = "redirect"
+        else:
+            disposition = "retire"
+        url = "/repo/" if index == 0 else f"/repo/project-{index}/"
+        destination = "/repo/project-1/" if disposition == "redirect" else ""
+        records.append(
+            {
+                "url": url,
+                "url_type": "index" if index == 0 else "canonical",
+                "canonical_url": url,
+                "candidate_disposition": disposition,
+                "destination_candidate": destination,
+                "rationale": f"{disposition} rationale",
+                "approval_status": "pending",
+            }
+        )
+        inventory.append(
+            {
+                "url": url,
+                "source_path": (
+                    "content/repo/_index.md"
+                    if index == 0
+                    else f"content/repo/project-{index}/index.md"
+                ),
+                "source_checksum": hashlib.sha256(url.encode()).hexdigest(),
+                "candidate_disposition": disposition,
+            }
+        )
+    candidate = {"approval_status": "pending", "records": records}
+    for relative, payload in (
+        (approved.CANDIDATE, candidate),
+        (approved.INVENTORY, {"records": inventory}),
+    ):
+        path = root / relative
+        path.parent.mkdir(parents=True, exist_ok=True)
+        path.write_text(json.dumps(payload), encoding="utf-8")
+
+
+def test_build_records_exact_approved_map(tmp_path: Path) -> None:
+    _write_inputs(tmp_path)
+
+    result = approved.build(tmp_path)
+
+    assert result["counts"] == {"keep": 11, "redirect": 1, "retire": 262, "total": 274}
+    assert result["approval"]["approver"] == "jmservera"
+    assert result["approval"]["gate_waiver"] is False
+    assert all(record["approval_status"] == "approved" for record in result["records"])
+
+
+def test_build_rejects_candidate_inventory_drift(tmp_path: Path) -> None:
+    _write_inputs(tmp_path)
+    inventory_path = tmp_path / approved.INVENTORY
+    inventory = json.loads(inventory_path.read_text(encoding="utf-8"))
+    inventory["records"][1]["candidate_disposition"] = "retire"
+    inventory_path.write_text(json.dumps(inventory), encoding="utf-8")
+
+    with pytest.raises(ValueError, match="Candidate drift"):
+        approved.build(tmp_path)
diff --git a/tests/test_generate_repository_disposition_candidate.py b/tests/test_generate_repository_disposition_candidate.py
new file mode 100644
index 0000000..18801cf
--- /dev/null
+++ b/tests/test_generate_repository_disposition_candidate.py
@@ -0,0 +1,169 @@
+from __future__ import annotations
+
+import json
+from datetime import date
+from pathlib import Path
+
+import pytest
+from jsonschema import ValidationError
+
+from scripts import generate_repository_disposition_candidate as candidate
+
+
+def _write_repo_page(path: Path) -> None:
+    path.parent.mkdir(parents=True, exist_ok=True)
+    path.write_text(
+        "---\n"
+        "generated_by: observatory_repo_pages\n"
+        "distinct_weekly_issues: 4\n"
+        "star_history: [1, 2]\n"
+        "weekly_appearances: [1, 2, 3, 4]\n"
+        "---\n",
+        encoding="utf-8",
+    )
+
+
+def _write_inputs(root: Path) -> None:
+    for path in candidate.INPUT_PATHS:
+        evidence = root / path
+        evidence.parent.mkdir(parents=True, exist_ok=True)
+        evidence.write_text("{}\n", encoding="utf-8")
+
+
+def _record(
+    url: str,
+    *,
+    url_type: str = "canonical",
+    canonical_url: str | None = None,
+    verdict: str = "NEUTRAL",
+    impressions: int | None = None,
+) -> dict[str, object]:
+    slug = url.strip("/").split("/")[-1]
+    return {
+        "url": url,
+        "url_type": url_type,
+        "canonical_url": canonical_url or url,
+        "source_path": f"content/repo/{slug}/index.md",
+        "source_checksum": "0" * 64,
+        "production": {"http_status": 200},
+        "inspection": {"verdict": verdict, "coverage_state": "test"},
+        "external_metrics": {
+            "search_impressions": impressions,
+            "sampled_inbound_link": None,
+            "referral_sessions": None,
+        },
+    }
+
+
+def test_build_candidate_keeps_value_redirects_alias_and_retires_rest(
+    tmp_path: Path,
+) -> None:
+    records = [
+        {
+            **_record("/repo/", url_type="index"),
+            "source_path": "content/repo/_index.md",
+        },
+        _record("/repo/valuable/", verdict="PASS", impressions=1),
+        _record("/repo/renamed/"),
+        _record(
+            "/repo/legacy/",
+            url_type="alias",
+            canonical_url="/repo/renamed/",
+            verdict="PASS",
+            impressions=1,
+        ),
+        _record("/repo/no-value/"),
+    ]
+    inventory = tmp_path / candidate.INVENTORY_PATH
+    inventory.parent.mkdir(parents=True, exist_ok=True)
+    inventory.write_text(json.dumps({"records": records}), encoding="utf-8")
+    (tmp_path / "content/repo/_index.md").parent.mkdir(parents=True, exist_ok=True)
+    (tmp_path / "content/repo/_index.md").write_text("---\n---\n", encoding="utf-8")
+    for slug in ("valuable", "renamed", "no-value"):
+        _write_repo_page(tmp_path / f"content/repo/{slug}/index.md")
+    rendered = tmp_path / "public"
+    rendered.mkdir()
+    (rendered / "index.html").write_text(
+        'Value',
+        encoding="utf-8",
+    )
+    _write_inputs(tmp_path)
+
+    payload = candidate.build_candidate(
+        tmp_path,
+        rendered,
+        reviewed_at=date(2026, 8, 11),
+    )
+    by_url = {record["url"]: record for record in payload["records"]}
+
+    assert payload["counts"] == {
+        "total": 5,
+        "keep": 3,
+        "redirect": 1,
+        "retire": 1,
+        "pending_approval": 5,
+    }
+    assert by_url["/repo/valuable/"]["candidate_disposition"] == "keep"
+    assert by_url["/repo/renamed/"]["candidate_disposition"] == "keep"
+    assert by_url["/repo/legacy/"]["candidate_disposition"] == "redirect"
+    assert by_url["/repo/no-value/"]["candidate_disposition"] == "retire"
+    assert by_url["/repo/valuable/"]["internal_link_count"] == 1
+    candidate.validate_candidate(payload, {"records": records})
+    candidate.validate_freshness(tmp_path, payload)
+
+
+def test_validate_candidate_rejects_approved_or_index_only_keep(tmp_path: Path) -> None:
+    records = [
+        {
+            **_record("/repo/", url_type="index"),
+            "source_path": "content/repo/_index.md",
+        },
+        _record("/repo/no-demand/", verdict="PASS"),
+    ]
+    inventory = tmp_path / candidate.INVENTORY_PATH
+    inventory.parent.mkdir(parents=True, exist_ok=True)
+    inventory.write_text(json.dumps({"records": records}), encoding="utf-8")
+    (tmp_path / "content/repo/_index.md").parent.mkdir(parents=True, exist_ok=True)
+    (tmp_path / "content/repo/_index.md").write_text("---\n---\n", encoding="utf-8")
+    _write_repo_page(tmp_path / "content/repo/no-demand/index.md")
+    rendered = tmp_path / "public"
+    rendered.mkdir()
+    _write_inputs(tmp_path)
+    payload = candidate.build_candidate(
+        tmp_path,
+        rendered,
+        reviewed_at=date(2026, 8, 11),
+    )
+    assert payload["records"][1]["candidate_disposition"] == "retire"
+    payload["records"][1]["candidate_disposition"] = "keep"
+    payload["counts"]["keep"] = 2
+    payload["counts"]["retire"] = 0
+
+    with pytest.raises(ValueError, match="Invalid candidate disposition"):
+        candidate.validate_candidate(payload, {"records": records})
+
+
+def test_validate_candidate_rejects_forged_approval(tmp_path: Path) -> None:
+    records = [
+        {
+            **_record("/repo/", url_type="index"),
+            "source_path": "content/repo/_index.md",
+        }
+    ]
+    inventory = tmp_path / candidate.INVENTORY_PATH
+    inventory.parent.mkdir(parents=True, exist_ok=True)
+    inventory.write_text(json.dumps({"records": records}), encoding="utf-8")
+    (tmp_path / "content/repo/_index.md").parent.mkdir(parents=True, exist_ok=True)
+    (tmp_path / "content/repo/_index.md").write_text("---\n---\n", encoding="utf-8")
+    rendered = tmp_path / "public"
+    rendered.mkdir()
+    _write_inputs(tmp_path)
+    payload = candidate.build_candidate(
+        tmp_path,
+        rendered,
+        reviewed_at=date(2026, 8, 11),
+    )
+    payload["approval_status"] = "approved"
+
+    with pytest.raises(ValidationError, match="'pending' was expected"):
+        candidate.validate_candidate(payload, {"records": records})
diff --git a/tests/test_generate_repository_summary.py b/tests/test_generate_repository_summary.py
new file mode 100644
index 0000000..ed6d5cb
--- /dev/null
+++ b/tests/test_generate_repository_summary.py
@@ -0,0 +1,120 @@
+from __future__ import annotations
+
+import json
+from pathlib import Path
+
+import pytest
+
+from scripts import generate_repository_summary as summary
+
+
+def _source_record(**overrides: object) -> dict[str, object]:
+    record: dict[str, object] = {
+        "date": "2026-08-03",
+        "repo_slug": "example-tool",
+        "repo_full_name": "example/tool",
+        "repo_name": "tool",
+        "repo_owner": "example",
+        "repo_url": "https://github.com/example/tool",
+        "repo_description": "A useful developer tool.",
+        "repo_language": "Python",
+        "tags": ["tools", "ai", "tools"],
+        "first_seen_week": "2026-W21",
+        "last_seen_week": "2026-W32",
+        "lifecycle": {"status": "active"},
+        "star_history": [
+            {"week": "2026-W29", "stars": 100, "delta": None},
+            {"week": "2026-W30", "stars": 110, "delta": 10},
+            {"week": "2026-W31", "stars": 125, "delta": 15},
+            {"week": "2026-W32", "stars": 145, "delta": 20},
+        ],
+    }
+    record.update(overrides)
+    return record
+
+
+def _write_source(root: Path, records: list[dict[str, object]]) -> None:
+    path = root / summary.SOURCE_PATH
+    path.parent.mkdir(parents=True, exist_ok=True)
+    path.write_text(json.dumps(records), encoding="utf-8")
+
+
+def test_build_payload_is_versioned_sanitized_and_deterministic(tmp_path: Path) -> None:
+    _write_source(tmp_path, [_source_record()])
+
+    first = summary.build_payload(tmp_path)
+    second = summary.build_payload(tmp_path)
+
+    assert first == second
+    assert first["schema_version"] == "1.0.0"
+    assert first["artifact_type"] == "repositories"
+    assert first["generated_at"] == "2026-08-03T00:00:00Z"
+    assert first["covered_period"] == {
+        "start": "2026-05-18",
+        "end": "2026-08-09",
+        "label": "2026-W21–2026-W32",
+    }
+    record = first["records"][0]
+    assert record["topics"] == ["ai", "tools"]
+    assert record["context_summary"] == "A useful developer tool."
+    assert record["recent_momentum"] == 45
+    assert record["star_history"][-1] == {
+        "period": "2026-W32",
+        "stars": 145,
+        "delta": 20,
+    }
+
+
+def test_records_default_to_recent_momentum_order(tmp_path: Path) -> None:
+    _write_source(
+        tmp_path,
+        [
+            _source_record(repo_slug="slow", repo_full_name="example/slow"),
+            _source_record(
+                repo_slug="fast",
+                repo_full_name="example/fast",
+                star_history=[
+                    {"week": "2026-W31", "stars": 100, "delta": None},
+                    {"week": "2026-W32", "stars": 200, "delta": 100},
+                ],
+            ),
+        ],
+    )
+
+    records = summary.build_payload(tmp_path)["records"]
+
+    assert [record["id"] for record in records] == ["fast", "slow"]
+
+
+def test_non_github_repository_url_is_rejected(tmp_path: Path) -> None:
+    _write_source(tmp_path, [_source_record(repo_url="https://example.com/tool")])
+
+    with pytest.raises(ValueError, match="https://github.com"):
+        summary.build_payload(tmp_path)
+
+
+def test_build_payload_rejects_empty_source(tmp_path: Path) -> None:
+    _write_source(tmp_path, [])
+
+    with pytest.raises(ValueError, match="non-empty list"):
+        summary.build_payload(tmp_path)
+
+
+def test_check_mode_requires_both_outputs(tmp_path: Path) -> None:
+    _write_source(tmp_path, [_source_record()])
+    rendered = summary.rendered_payload(tmp_path)
+    first = tmp_path / summary.DEFAULT_OUTPUTS[0]
+    first.parent.mkdir(parents=True, exist_ok=True)
+    first.write_text(rendered, encoding="utf-8")
+
+    with pytest.raises(SystemExit, match="static/data/repositories.json"):
+        summary.main(["--root", str(tmp_path), "--check"])
+
+
+def test_long_context_summary_stays_bounded(tmp_path: Path) -> None:
+    _write_source(tmp_path, [_source_record(repo_description="word " * 100)])
+
+    record = summary.build_payload(tmp_path)["records"][0]
+
+    assert len(record["context_summary"]) <= 240
+    assert record["context_summary"].endswith("…")
